insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('chief-of-staff', 'Chief of Staff', 'CLAW', 'chief', 'A persistent assistant that prepares your day, tracks commitments and keeps a decision log you can search later.', 'CONFIGURABLE', true, '{"slug":"chief-of-staff","name":"Chief of Staff","family":"CLAW","foundation":"chief","summary":"A persistent assistant that prepares your day, tracks commitments and keeps a decision log you can search later.","description":"Chief of Staff reads your calendar, inbox and task lists each morning and writes a short briefing: what is due, who is waiting on you and which meetings need preparation. It keeps a running decision log with links back to the source message, drafts follow-ups for you to approve, and never sends or accepts anything on your behalf without a recorded approval.","outcomes":["A written morning briefing before your first meeting","Commitments from email and meetings captured as tracked follow-ups","A searchable decision log with links to the original source","Follow-up drafts queued for one-tap approval"],"integrations":["Google Workspace","Microsoft 365","Slack","Notion","Linear"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"DELETE","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"OPERATOR","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["briefing","follow-up","executive"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('executive-inbox', 'Executive Inbox Assistant', 'CLAW', 'chief', 'Triage a busy inbox into decide, delegate, reply and archive — with replies drafted in your voice and held for approval.', 'CONFIGURABLE', true, '{"slug":"executive-inbox","name":"Executive Inbox Assistant","family":"CLAW","foundation":"chief","summary":"Triage a busy inbox into decide, delegate, reply and archive — with replies drafted in your voice and held for approval.","description":"The Executive Inbox Assistant sorts incoming mail by what it needs from you, drafts replies that follow your tone guide and flags anything with money, legal terms or unknown senders. Message content is treated as untrusted data: instructions inside an email never change what the assistant is allowed to do. Nothing leaves your mailbox until you approve it.","outcomes":["Inbox sorted into decide, delegate, reply and archive","Reply drafts in your tone, held until you approve","Payment, contract and unknown-sender messages flagged for review"],"integrations":["Gmail","Outlook","Slack"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["email","triage"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('meeting-follow-through', 'Meeting Prep & Follow-Through', 'CLAW', 'chief', 'Briefs you before each meeting and turns the notes afterwards into owners, dates and drafted recaps.', 'CONFIGURABLE', true, '{"slug":"meeting-follow-through","name":"Meeting Prep & Follow-Through","family":"CLAW","foundation":"chief","summary":"Briefs you before each meeting and turns the notes afterwards into owners, dates and drafted recaps.","description":"Before a meeting it assembles the relevant threads, documents and open items into a one-page brief. Afterwards it turns notes or transcripts into action items with owners and due dates, drafts the recap for the attendees and keeps checking until each item is closed. Recaps are sent only after you approve them.","outcomes":["A one-page brief for every meeting on your calendar","Action items with owners and dates extracted from notes","Recap emails drafted for approval, not sent automatically"],"integrations":["Google Calendar","Outlook Calendar","Zoom","Google Docs","Notion"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["meetings","action-items"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('research-desk', 'Research Desk', 'CLAW', 'research', 'A research assistant with a persistent source library, so every answer comes with citations you can open and check.', 'CONFIGURABLE', true, '{"slug":"research-desk","name":"Research Desk","family":"CLAW","foundation":"research","summary":"A research assistant with a persistent source library, so every answer comes with citations you can open and check.","description":"Research Desk keeps a library of the sources you and it have gathered — papers, filings, web pages and internal documents — and answers questions with citations to specific passages. Web content is handled as untrusted data. It tracks which claims are well supported and which rest on a single source, and it remembers corrections you make.","outcomes":["Answers with citations to the exact passage used","A reusable, searchable source library per project","Weakly supported claims marked as such","Corrections you make are remembered with their provenance"],"integrations":["Web search","Google Drive","Zotero","SharePoint"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["citations","sources","analysis"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('support-desk-assistant', 'Support Desk Assistant', 'CLAW', 'support', 'Drafts accurate replies from your help centre and past tickets, and escalates anything outside policy to a person.', 'CONFIGURABLE', true, '{"slug":"support-desk-assistant","name":"Support Desk Assistant","family":"CLAW","foundation":"support","summary":"Drafts accurate replies from your help centre and past tickets, and escalates anything outside policy to a person.","description":"The Support Desk Assistant reads each new ticket, finds the relevant help-centre articles and similar resolved tickets, and drafts a reply for an agent to approve. Refunds, account changes and anything outside your written policy are escalated rather than answered. Customer messages are treated as untrusted input.","outcomes":["Reply drafts grounded in your help centre and resolved tickets","Policy-sensitive requests escalated with a summary","Consistent tone across agents and shifts"],"integrations":["Zendesk","Intercom","Freshdesk","Help Scout"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["tickets","customer-service"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('sales-desk-assistant', 'Sales Desk Assistant', 'CLAW', 'crm-sales', 'Keeps your CRM current from email and calls, and drafts next-step outreach for each open deal.', 'CONFIGURABLE', true, '{"slug":"sales-desk-assistant","name":"Sales Desk Assistant","family":"CLAW","foundation":"crm-sales","summary":"Keeps your CRM current from email and calls, and drafts next-step outreach for each open deal.","description":"It reads your sales conversations, updates contact and deal records with what actually happened, and suggests the next step for every open opportunity. Outreach is drafted for you to edit and approve; bulk sends are capped per hour and never go to unverified recipients.","outcomes":["CRM records updated from real conversations","A next step suggested for every open deal","Outreach drafts with per-hour send limits"],"integrations":["HubSpot","Salesforce","Pipedrive","Gmail","Outlook"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"DELETE","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"OPERATOR","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["crm","pipeline","outreach"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('operations-coordinator', 'Operations Coordinator', 'CLAW', 'operations', 'Runs recurring checklists, chases handoffs between teams and raises exceptions before they become incidents.', 'CONFIGURABLE', true, '{"slug":"operations-coordinator","name":"Operations Coordinator","family":"CLAW","foundation":"operations","summary":"Runs recurring checklists, chases handoffs between teams and raises exceptions before they become incidents.","description":"The Operations Coordinator owns your recurring operational rhythms: opening and closing checklists, shift handoffs, weekly reviews. It notices when a step is late or skipped, asks the responsible person, and escalates exceptions with context. Schedule changes affecting people outside your organisation require approval.","outcomes":["Recurring checklists run and tracked to completion","Late or skipped steps chased automatically","Exceptions escalated with the context needed to act"],"integrations":["Slack","Microsoft Teams","Asana","Google Sheets"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"OPERATOR","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["checklists","handoffs"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('bookkeeping-assistant', 'Bookkeeping Assistant', 'CLAW', 'finance-admin', 'Categorises transactions, prepares reconciliation drafts and chases missing receipts — and never moves money.', 'CONFIGURABLE', true, '{"slug":"bookkeeping-assistant","name":"Bookkeeping Assistant","family":"CLAW","foundation":"finance-admin","summary":"Categorises transactions, prepares reconciliation drafts and chases missing receipts — and never moves money.","description":"The Bookkeeping Assistant proposes categories for new transactions, matches receipts, drafts reconciliation notes for your accountant and chases missing paperwork. It has no ability to pay, transfer or approve spending; those actions are denied at the policy level, not just hidden in the interface.","outcomes":["Transactions categorised with a reason for each suggestion","Missing receipts chased on a schedule","Reconciliation drafts ready for accountant review"],"integrations":["QuickBooks","Xero","Google Drive","Dext"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"SPEND","rule":"deny"},{"action":"DELETE","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["accounting","receipts"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('developer-workspace', 'Developer Workspace Assistant', 'CLAW', 'developer-builder', 'A coding assistant in an isolated workspace: it can branch, edit and run tests, but merging and deploying need you.', 'CONFIGURABLE', true, '{"slug":"developer-workspace","name":"Developer Workspace Assistant","family":"CLAW","foundation":"developer-builder","summary":"A coding assistant in an isolated workspace: it can branch, edit and run tests, but merging and deploying need you.","description":"The Developer Workspace Assistant works inside a bounded copy of your repository with an allowlist of commands. It can read code, open branches, make edits and run your test suite in a sandbox. Merging, publishing packages and deploying are approval-gated, and it cannot reach hosts or paths outside its allowlist.","outcomes":["Changes proposed on branches with passing tests","Commands limited to an explicit allowlist","Merges and deploys only after human approval"],"integrations":["GitHub","GitLab","Linear","Jira"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"DEPLOY","rule":"approval"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"OPERATOR","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","gpu-24gb","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["code","tests","sandbox"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('team-memory', 'Team Memory', 'CLAW', 'knowledge-memory', 'Shared organisational memory that records where each fact came from and keeps a history of corrections.', 'CONFIGURABLE', true, '{"slug":"team-memory","name":"Team Memory","family":"CLAW","foundation":"knowledge-memory","summary":"Shared organisational memory that records where each fact came from and keeps a history of corrections.","description":"Team Memory captures decisions, definitions and how-tos from the places your team already works. Every memory keeps its provenance — who said it, where and when — and corrections are stored as new versions rather than silent overwrites. Retention rules and export are built in, and secrets are rejected before they can be stored.","outcomes":["Answers that cite the conversation or document they came from","Corrections tracked as versions, never silent overwrites","Retention rules and full export per workspace"],"integrations":["Slack","Confluence","Notion","Google Drive"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["balanced","local-first","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["memory","provenance","wiki"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('household-organizer', 'Household Organizer', 'CLAW', 'family-play', 'A family assistant for calendars, chores, meal plans and school notices, with guardian controls on every account.', 'CONFIGURABLE', true, '{"slug":"household-organizer","name":"Household Organizer","family":"CLAW","foundation":"family-play","summary":"A family assistant for calendars, chores, meal plans and school notices, with guardian controls on every account.","description":"Household Organizer merges family calendars, turns school and club notices into dates and checklists, proposes weekly meal plans and shopping lists and keeps chores fair. Guardians control what children''s accounts can see and do. Purchases and messages to people outside the household always require a guardian''s approval.","outcomes":["One family calendar built from every source","School notices turned into dates and checklists","Meal plans and shopping lists drafted weekly"],"integrations":["Google Calendar","Apple Calendar","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"SPEND","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","balanced"],"compute":["cpu","customer-hardware"],"deployments":["managed-cell","edge-device"],"maturity":"CONFIGURABLE","tags":["family","calendar","guardian"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('study-companion', 'Study Companion', 'CLAW', 'learning-maker', 'A patient tutor that remembers what you have covered, quizzes you on it and plans the next session.', 'CONFIGURABLE', true, '{"slug":"study-companion","name":"Study Companion","family":"CLAW","foundation":"learning-maker","summary":"A patient tutor that remembers what you have covered, quizzes you on it and plans the next session.","description":"Study Companion builds a study plan from your syllabus or goals, explains concepts at the level you ask for, and uses spaced repetition to quiz you on what you have covered. It remembers where you struggled and adjusts. It can run on local models for privacy, and it never submits work on your behalf.","outcomes":["A study plan built from your syllabus or goals","Spaced-repetition quizzes on material already covered","Sessions that adapt to where you struggled"],"integrations":["Google Classroom","Anki export","PDF library"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"PUBLISH","rule":"draft-only"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","local-only","lowest-cost"],"compute":["cpu","customer-hardware","unified-memory-node"],"deployments":["managed-cell","edge-device"],"maturity":"CONFIGURABLE","tags":["tutor","spaced-repetition"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('brand-studio-assistant', 'Brand Studio Assistant', 'CLAW', 'marketing-creative', 'Drafts on-brand copy and briefs from your style guide, and holds everything for review before it is published.', 'CONFIGURABLE', true, '{"slug":"brand-studio-assistant","name":"Brand Studio Assistant","family":"CLAW","foundation":"marketing-creative","summary":"Drafts on-brand copy and briefs from your style guide, and holds everything for review before it is published.","description":"Brand Studio Assistant learns your voice, vocabulary and visual rules from your brand guide and past work. It drafts posts, product copy, briefs and variations for testing, checks each draft against the guide and explains any deviation. Publishing to any channel requires approval.","outcomes":["Drafts checked against your brand guide with explanations","Variations prepared for testing","Nothing published without approval"],"integrations":["Figma","Google Docs","Buffer","Webflow","Notion"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","unified-memory-node"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["brand","copy","content"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('lead-to-customer', 'Lead-to-Customer Workflow', 'FLOW', 'crm-sales', 'Takes a new lead from verification and research through an approved proposal, payment and go-live — one explicit step at a time.', 'CONFIGURABLE', true, '{"slug":"lead-to-customer","name":"Lead-to-Customer Workflow","family":"FLOW","foundation":"crm-sales","summary":"Takes a new lead from verification and research through an approved proposal, payment and go-live — one explicit step at a time.","description":"Lead-to-Customer moves each lead through named states: source verification, research, qualification, proposal draft, approval, send, reply, payment confirmation, provisioning review, configuration validation, acceptance testing and deployment approval. The workflow survives restarts without repeating completed steps, duplicate payment notifications cause a single transition, and a failed acceptance test blocks go-live.","outcomes":["Every lead in exactly one named state, with a full timeline","Proposals sent only after approval of the exact draft","Duplicate notifications suppressed without duplicate side effects","Go-live blocked until acceptance tests pass and activation is approved"],"integrations":["HubSpot","Salesforce","Gmail","Stripe"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"SPEND","rule":"deny"},{"action":"DEPLOY","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["durable","approvals","pipeline"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('invoice-approval', 'Invoice Approval Workflow', 'FLOW', 'finance-admin', 'Routes supplier invoices through extraction, policy checks and the right approvers before anything is scheduled for payment.', 'CONFIGURABLE', true, '{"slug":"invoice-approval","name":"Invoice Approval Workflow","family":"FLOW","foundation":"finance-admin","summary":"Routes supplier invoices through extraction, policy checks and the right approvers before anything is scheduled for payment.","description":"Each invoice is extracted into a validated record, matched against purchase orders and checked against your approval matrix. It waits for the right approver, records the decision and prepares the payment batch for your finance team. The workflow never executes a payment; scheduling payment is a separate, approval-gated step in your own finance system.","outcomes":["Invoices matched to purchase orders with mismatches flagged","Approval routed by amount and cost centre","Payment batches prepared, never executed automatically"],"integrations":["QuickBooks","Xero","NetSuite","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SPEND","rule":"deny"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["local-first","customer-provider"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["accounts-payable","approvals"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('employee-onboarding', 'Employee Onboarding Workflow', 'FLOW', 'operations', 'Coordinates accounts, equipment, paperwork and first-week plans for every new hire, with each step owned and tracked.', 'CONFIGURABLE', true, '{"slug":"employee-onboarding","name":"Employee Onboarding Workflow","family":"FLOW","foundation":"operations","summary":"Coordinates accounts, equipment, paperwork and first-week plans for every new hire, with each step owned and tracked.","description":"From signed offer to the end of the first week, the onboarding workflow creates the checklist for the role, requests accounts and equipment from the right teams, chases paperwork and schedules introductions. Account creation in production systems is approval-gated, and the workflow resumes cleanly if a step fails part-way.","outcomes":["A role-specific onboarding checklist for every hire","Account and equipment requests routed and tracked","Production access granted only after approval"],"integrations":["BambooHR","Google Workspace","Okta","Slack"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["hr","onboarding"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('refund-request', 'Refund Request Workflow', 'FLOW', 'support', 'Checks refund requests against order history and policy, then queues the refund for an agent to approve.', 'CONFIGURABLE', true, '{"slug":"refund-request","name":"Refund Request Workflow","family":"FLOW","foundation":"support","summary":"Checks refund requests against order history and policy, then queues the refund for an agent to approve.","description":"The refund workflow validates each request against the order, delivery status and your written refund policy. Clear cases are prepared with a recommended decision; unusual ones go to a person with a summary. Issuing a refund is always an approval-gated action with per-day limits.","outcomes":["Refund requests checked against order data and policy","Recommended decision with the reasoning attached","Refunds issued only after approval, within daily limits"],"integrations":["Shopify","Stripe","Zendesk","Gorgias"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SPEND","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["refunds","policy"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('purchase-order', 'Purchase Order Workflow', 'FLOW', 'commerce-inventory', 'Turns purchase requests into validated purchase orders, routes approvals and tracks delivery against what was ordered.', 'CONFIGURABLE', true, '{"slug":"purchase-order","name":"Purchase Order Workflow","family":"FLOW","foundation":"commerce-inventory","summary":"Turns purchase requests into validated purchase orders, routes approvals and tracks delivery against what was ordered.","description":"Purchase requests are normalised into structured orders, checked against budget and preferred suppliers, and routed for approval. Once approved, the draft order is ready to send to the supplier, and the workflow tracks confirmations and deliveries. Sending an order to a supplier is an approval-gated action.","outcomes":["Structured purchase orders from free-text requests","Budget and supplier checks before approval","Delivery tracked against the approved order"],"integrations":["NetSuite","Odoo","Google Sheets","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"SPEND","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["procurement","suppliers"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('content-publishing', 'Content Publishing Workflow', 'FLOW', 'marketing-creative', 'Moves content from brief to draft to review to scheduled publication, with brand and legal checks in between.', 'CONFIGURABLE', true, '{"slug":"content-publishing","name":"Content Publishing Workflow","family":"FLOW","foundation":"marketing-creative","summary":"Moves content from brief to draft to review to scheduled publication, with brand and legal checks in between.","description":"A content piece moves through explicit states: brief, draft, brand check, legal check where required, approval and scheduling. Each state records who acted and when. Publication happens only from the approved version, and any edit after approval sends the piece back for re-approval.","outcomes":["Every piece in a visible state from brief to published","Edits after approval automatically require re-approval","Scheduled publication from the approved version only"],"integrations":["WordPress","Webflow","Contentful","Buffer"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","maximum-intelligence"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["editorial","approvals"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('vendor-due-diligence', 'Vendor Due Diligence Workflow', 'FLOW', 'security-compliance', 'Collects questionnaires, evidence and risk ratings for new vendors, and holds onboarding until review is complete.', 'CONFIGURABLE', true, '{"slug":"vendor-due-diligence","name":"Vendor Due Diligence Workflow","family":"FLOW","foundation":"security-compliance","summary":"Collects questionnaires, evidence and risk ratings for new vendors, and holds onboarding until review is complete.","description":"New vendors are sent the right questionnaire for their risk tier, answers and evidence are checked for completeness, and a draft risk rating is prepared for your reviewer. The vendor cannot move to approved until required evidence is present and a reviewer signs off. Outbound requests to vendors are approval-gated.","outcomes":["Questionnaires matched to each vendor''s risk tier","Completeness checks on answers and evidence","Approval blocked until evidence and sign-off are recorded"],"integrations":["Google Forms","Vanta","Drata","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["third-party-risk","evidence"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('contract-review', 'Contract Review Workflow', 'FLOW', 'operations', 'Compares incoming contracts to your playbook, drafts redlines and tracks each agreement to signature.', 'CONFIGURABLE', true, '{"slug":"contract-review","name":"Contract Review Workflow","family":"FLOW","foundation":"operations","summary":"Compares incoming contracts to your playbook, drafts redlines and tracks each agreement to signature.","description":"Incoming contracts are compared clause by clause with your negotiation playbook. Deviations are highlighted with suggested fallback language, and the workflow tracks each agreement through legal review, business approval and signature. It prepares redlines but never signs or sends a contract without approval.","outcomes":["Deviations from your playbook highlighted clause by clause","Suggested fallback language drafted for review","Status tracked from receipt to signature"],"integrations":["DocuSign","Google Drive","SharePoint","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["local-first","customer-provider","maximum-intelligence"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["legal-ops","redlines"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('release-runbook', 'Release & Incident Runbook', 'FLOW', 'developer-builder', 'Executes your release and incident runbooks step by step, pausing for sign-off at every production-affecting step.', 'CONFIGURABLE', true, '{"slug":"release-runbook","name":"Release & Incident Runbook","family":"FLOW","foundation":"developer-builder","summary":"Executes your release and incident runbooks step by step, pausing for sign-off at every production-affecting step.","description":"Runbooks become explicit workflows: pre-flight checks, change announcement, deployment, verification and rollback. Each production-affecting step waits for an approval and records who approved it. If a step fails, the workflow stops in a known state and offers the documented recovery path instead of guessing.","outcomes":["Runbooks executed consistently, step by step","Production changes only after recorded sign-off","Failures stop in a known state with the recovery path"],"integrations":["GitHub Actions","PagerDuty","Slack","Datadog"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DEPLOY","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["runbooks","incidents","releases"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('appointment-booking', 'Appointment Booking Workflow', 'FLOW', 'voice-reception', 'Handles booking requests from web, email and phone notes, checks availability and confirms on approval rules you set.', 'CONFIGURABLE', true, '{"slug":"appointment-booking","name":"Appointment Booking Workflow","family":"FLOW","foundation":"voice-reception","summary":"Handles booking requests from web, email and phone notes, checks availability and confirms on approval rules you set.","description":"Booking requests from any channel are turned into structured requests, checked against staff availability and your booking rules, and either confirmed within your rules or held for a person. Reminders and reschedules follow the same explicit states, and double-booking is prevented by design rather than by luck.","outcomes":["Booking requests from any channel handled the same way","Confirmations only within the rules you set","Double-booking prevented by explicit state checks"],"integrations":["Google Calendar","Calendly","Twilio","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["scheduling","reminders"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('scheduled-research-report', 'Scheduled Research Report', 'FLOW', 'research', 'Produces a recurring market or competitor report with validated citations, delivered for review on your schedule.', 'CONFIGURABLE', true, '{"slug":"scheduled-research-report","name":"Scheduled Research Report","family":"FLOW","foundation":"research","summary":"Produces a recurring market or competitor report with validated citations, delivered for review on your schedule.","description":"On the schedule you choose, the workflow gathers sources, extracts findings, validates that every claim has a citation and assembles the report. If sources are unavailable or validation fails, it stops and tells you instead of publishing a thinner report. Distribution to recipients requires approval.","outcomes":["A recurring report with a citation for every claim","Validation failures stop the run instead of weakening it","Distribution only after approval"],"integrations":["Web search","RSS","Google Docs","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["reports","monitoring"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('access-review', 'Quarterly Access Review', 'FLOW', 'security-compliance', 'Collects who-has-access-to-what, asks each owner to confirm or revoke, and records the evidence for audit.', 'CONFIGURABLE', true, '{"slug":"access-review","name":"Quarterly Access Review","family":"FLOW","foundation":"security-compliance","summary":"Collects who-has-access-to-what, asks each owner to confirm or revoke, and records the evidence for audit.","description":"The access review workflow pulls current access lists, sends each system owner their review, chases late responses and records every decision. Revocations are prepared as change requests and executed only after approval. The finished review is exported as audit evidence with timestamps and reviewers.","outcomes":["Access lists gathered and assigned to owners","Every confirm or revoke decision recorded","Audit-ready evidence exported at the end"],"integrations":["Okta","Google Workspace","Microsoft Entra ID","GitHub"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["access","audit"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('restock-reorder', 'Restock & Reorder Workflow', 'FLOW', 'commerce-inventory', 'Watches stock levels, drafts reorders from supplier lead times and holds them for approval before ordering.', 'CONFIGURABLE', true, '{"slug":"restock-reorder","name":"Restock & Reorder Workflow","family":"FLOW","foundation":"commerce-inventory","summary":"Watches stock levels, drafts reorders from supplier lead times and holds them for approval before ordering.","description":"The restock workflow tracks stock against reorder points and supplier lead times, drafts reorder quantities with the reasoning shown, and holds each order for approval. It follows the order through confirmation and receipt, and flags short deliveries. Spending limits per day and per supplier are enforced.","outcomes":["Reorders drafted before stock runs out","Quantities explained using lead times and sales history","Daily and per-supplier spending ceilings enforced"],"integrations":["Shopify","Square","Lightspeed","Google Sheets"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SPEND","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"langgraph","modelPolicies":["balanced","local-first","lowest-cost"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["inventory","reorder"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('marketing-crew', 'Marketing Crew', 'CREW', 'marketing-creative', 'A strategist, copywriter, editor and brand reviewer working one campaign brief, with you approving what ships.', 'CONFIGURABLE', true, '{"slug":"marketing-crew","name":"Marketing Crew","family":"CREW","foundation":"marketing-creative","summary":"A strategist, copywriter, editor and brand reviewer working one campaign brief, with you approving what ships.","description":"The Marketing Crew takes a campaign brief and divides the work: the strategist proposes angles and channels, the copywriter drafts, the editor tightens and the brand reviewer checks against your guide. The crew shares one task board and one budget. Anything that would be published or sent waits for your approval.","outcomes":["Campaign plans with angles, channels and drafts in one pass","Every draft reviewed against your brand guide","One shared budget and task board for the whole crew"],"integrations":["Google Docs","Figma","HubSpot","Buffer","Notion"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["campaigns","team"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('research-crew', 'Research Crew', 'CREW', 'research', 'A lead researcher, analysts and a fact-checker that turn a question into a sourced brief you can defend.', 'CONFIGURABLE', true, '{"slug":"research-crew","name":"Research Crew","family":"CREW","foundation":"research","summary":"A lead researcher, analysts and a fact-checker that turn a question into a sourced brief you can defend.","description":"The lead researcher breaks your question into lines of inquiry, analysts investigate each one and the fact-checker verifies every claim against its cited source before the brief is assembled. Disagreements between analysts are shown, not hidden. Web and document content is treated as untrusted data throughout.","outcomes":["Complex questions split into tracked lines of inquiry","Every claim checked against its source","Disagreements between analysts surfaced in the brief"],"integrations":["Web search","Google Drive","SharePoint","Zotero"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["fact-checking","briefs"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('recruiting-crew', 'Recruiting Crew', 'CREW', 'operations', 'Sourcing, screening and scheduling specialists that prepare shortlists — hiring decisions always stay with people.', 'CONFIGURABLE', true, '{"slug":"recruiting-crew","name":"Recruiting Crew","family":"CREW","foundation":"operations","summary":"Sourcing, screening and scheduling specialists that prepare shortlists — hiring decisions always stay with people.","description":"The sourcer builds a candidate list from your criteria, the screener summarises applications against the job''s requirements with the evidence for each point, and the scheduler proposes interview slots. The crew never rejects or hires anyone; it prepares shortlists and drafts for your hiring team to decide on.","outcomes":["Shortlists with evidence for each requirement","Interview scheduling drafted across calendars","Hiring and rejection decisions kept with people"],"integrations":["Greenhouse","Lever","LinkedIn","Google Calendar"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["hiring","screening"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('sales-development-crew', 'Sales Development Crew', 'CREW', 'crm-sales', 'Account research, qualification and personalised outreach drafted by a coordinated team, sent only on approval.', 'CONFIGURABLE', true, '{"slug":"sales-development-crew","name":"Sales Development Crew","family":"CREW","foundation":"crm-sales","summary":"Account research, qualification and personalised outreach drafted by a coordinated team, sent only on approval.","description":"A researcher profiles each target account, a qualifier scores it against your ideal-customer definition with reasons, and a writer drafts personalised outreach. Sends are approval-gated and rate-limited, recipients are checked against suppression lists, and every contact attempt is logged to your CRM.","outcomes":["Account research and qualification with reasons","Personalised outreach drafts ready for review","Suppression lists and per-hour send limits enforced"],"integrations":["HubSpot","Salesforce","Apollo","Gmail"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["outbound","qualification"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('support-escalation-crew', 'Support Escalation Crew', 'CREW', 'support', 'A triage lead, investigator and writer that handle complex tickets together and hand you a resolution plan.', 'CONFIGURABLE', true, '{"slug":"support-escalation-crew","name":"Support Escalation Crew","family":"CREW","foundation":"support","summary":"A triage lead, investigator and writer that handle complex tickets together and hand you a resolution plan.","description":"For tickets that need more than a template, the triage lead gathers context, the investigator reproduces the issue from logs and account data it is allowed to read, and the writer drafts the customer reply and the internal bug report. Account changes and credits are approval-gated.","outcomes":["Complex tickets investigated with evidence attached","Customer reply and internal bug report drafted together","Account changes and credits held for approval"],"integrations":["Zendesk","Jira","Sentry","Intercom"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"SPEND","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["escalations","bugs"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('launch-room-crew', 'Launch Room Crew', 'CREW', 'chief', 'A coordinated team that keeps a product launch on track: plan, dependencies, comms drafts and a daily status.', 'CONFIGURABLE', true, '{"slug":"launch-room-crew","name":"Launch Room Crew","family":"CREW","foundation":"chief","summary":"A coordinated team that keeps a product launch on track: plan, dependencies, comms drafts and a daily status.","description":"The Launch Room Crew keeps a launch plan with owners and dates, tracks dependencies across teams, drafts internal and external communications and writes a daily status for leadership. It highlights slips early and proposes options. Announcements are published only after approval.","outcomes":["A launch plan with owners, dates and dependencies","Daily status that highlights slips early","Announcements drafted and held for approval"],"integrations":["Asana","Jira","Slack","Google Docs"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["launch","program-management"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('finance-close-crew', 'Month-End Close Crew', 'CREW', 'finance-admin', 'Specialists that prepare reconciliations, accrual drafts and variance notes so your close starts further ahead.', 'CONFIGURABLE', true, '{"slug":"finance-close-crew","name":"Month-End Close Crew","family":"CREW","foundation":"finance-admin","summary":"Specialists that prepare reconciliations, accrual drafts and variance notes so your close starts further ahead.","description":"The close crew prepares account reconciliations, drafts accrual and prepayment schedules, and writes variance explanations for review. Every figure links to the underlying records. Journal entries are drafts only; posting to the ledger requires your accountant''s approval.","outcomes":["Reconciliations prepared with links to source records","Accrual and variance drafts ready for review","Journal entries posted only after approval"],"integrations":["NetSuite","QuickBooks","Xero","Google Sheets"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"approval"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["local-first","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["close","reconciliation"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('code-review-crew', 'Code Review Crew', 'CREW', 'developer-builder', 'Reviewers for correctness, security and tests that comment on pull requests — merging stays with your team.', 'CONFIGURABLE', true, '{"slug":"code-review-crew","name":"Code Review Crew","family":"CREW","foundation":"developer-builder","summary":"Reviewers for correctness, security and tests that comment on pull requests — merging stays with your team.","description":"Each pull request gets a correctness reviewer, a security reviewer and a test reviewer. They comment with specific lines and reasons, and the crew lead summarises what must change before merge. The crew can suggest changes but cannot merge, deploy or change repository settings.","outcomes":["Correctness, security and test reviews on every pull request","Line-specific comments with reasons","No merge, deploy or settings access"],"integrations":["GitHub","GitLab","Bitbucket"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"draft-only"},{"action":"DEPLOY","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["pull-requests","security-review"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('compliance-evidence-crew', 'Compliance Evidence Crew', 'CREW', 'security-compliance', 'Collectors and a reviewer that gather control evidence, map it to your framework and flag the gaps.', 'CONFIGURABLE', true, '{"slug":"compliance-evidence-crew","name":"Compliance Evidence Crew","family":"CREW","foundation":"security-compliance","summary":"Collectors and a reviewer that gather control evidence, map it to your framework and flag the gaps.","description":"Collectors gather screenshots, configuration exports and policy documents for each control; the reviewer maps them to your control framework and notes what is missing or stale. The result is a gap list and an evidence folder for your auditor. The crew does not certify anything — it prepares the evidence.","outcomes":["Evidence collected and mapped to each control","Missing or stale evidence listed as gaps","An organised evidence folder for your auditor"],"integrations":["Google Drive","AWS","GitHub","Okta","Jira"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["audit","controls"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('merchandising-crew', 'Merchandising Crew', 'CREW', 'commerce-inventory', 'A catalog editor, pricing analyst and promo planner that prepare product updates for your store to approve.', 'CONFIGURABLE', true, '{"slug":"merchandising-crew","name":"Merchandising Crew","family":"CREW","foundation":"commerce-inventory","summary":"A catalog editor, pricing analyst and promo planner that prepare product updates for your store to approve.","description":"The catalog editor improves titles, descriptions and attributes; the pricing analyst proposes price changes with the data behind them; the promo planner drafts promotions within the margin rules you set. Nothing changes on your storefront until you approve the batch.","outcomes":["Product content improved in reviewable batches","Price proposals with supporting data","Promotions drafted within your margin rules"],"integrations":["Shopify","BigCommerce","WooCommerce","Google Merchant Center"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["ecommerce","pricing"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('knowledge-curation-crew', 'Knowledge Curation Crew', 'CREW', 'knowledge-memory', 'Curators that find outdated, duplicated or contradictory documentation and propose fixes with sources.', 'CONFIGURABLE', true, '{"slug":"knowledge-curation-crew","name":"Knowledge Curation Crew","family":"CREW","foundation":"knowledge-memory","summary":"Curators that find outdated, duplicated or contradictory documentation and propose fixes with sources.","description":"The crew scans your knowledge base for pages that contradict each other, reference retired systems or duplicate content. Each finding comes with evidence and a proposed fix — merge, update or archive — for the page owner to approve. Archiving and deletion are approval-gated.","outcomes":["Contradictory and outdated pages found with evidence","Merge, update or archive proposals for owners","No page removed without approval"],"integrations":["Confluence","Notion","SharePoint","Google Drive"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["documentation","hygiene"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('curriculum-design-crew', 'Curriculum Design Crew', 'CREW', 'learning-maker', 'An instructional designer, subject expert and assessor that build a course outline, lessons and quizzes from your goals.', 'CONFIGURABLE', true, '{"slug":"curriculum-design-crew","name":"Curriculum Design Crew","family":"CREW","foundation":"learning-maker","summary":"An instructional designer, subject expert and assessor that build a course outline, lessons and quizzes from your goals.","description":"Give the crew learning goals and source material; the instructional designer drafts the course structure, the subject expert writes lesson content grounded in your sources and the assessor writes quizzes aligned to each objective. You review and edit before anything is published to learners.","outcomes":["Course outline aligned to your learning goals","Lessons grounded in your source material","Quizzes mapped to each objective"],"integrations":["Google Docs","Moodle","Canvas","Notion"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["balanced","maximum-intelligence","customer-provider"],"compute":["cpu","gpu-48gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["courses","assessment"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('family-game-crew', 'Family Game Master Crew', 'CREW', 'family-play', 'A storyteller, rules keeper and puzzle maker that run age-appropriate games, with guardian controls throughout.', 'CONFIGURABLE', true, '{"slug":"family-game-crew","name":"Family Game Master Crew","family":"CREW","foundation":"family-play","summary":"A storyteller, rules keeper and puzzle maker that run age-appropriate games, with guardian controls throughout.","description":"The storyteller runs an adventure, the rules keeper keeps play fair and explains rules, and the puzzle maker creates challenges pitched to each player''s age. Guardians set content limits and session length. The crew has no ability to purchase, message outside the family or share anything publicly.","outcomes":["Story games pitched to each player''s age","Guardian-set content limits and session lengths","No purchases, outside messaging or public sharing"],"integrations":["Printable PDFs","Family calendar"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"SPEND","rule":"deny"},{"action":"PUBLISH","rule":"draft-only"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"crewai","modelPolicies":["local-first","lowest-cost"],"compute":["cpu","customer-hardware"],"deployments":["managed-cell","edge-device"],"maturity":"CONFIGURABLE","tags":["games","kids","guardian"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('invoice-extractor', 'Invoice Extractor', 'STRICT', 'finance-admin', 'Turns invoices and receipts into validated records — totals, tax, line items — or rejects them with a reason.', 'CONFIGURABLE', true, '{"slug":"invoice-extractor","name":"Invoice Extractor","family":"STRICT","foundation":"finance-admin","summary":"Turns invoices and receipts into validated records — totals, tax, line items — or rejects them with a reason.","description":"Every document becomes a record that must pass a strict schema: supplier, dates, currency, line items, tax and totals that add up. Anything that fails validation is rejected with the specific reason instead of being guessed at. Validated records are written to your accounting system as drafts.","outcomes":["Structured invoice records with arithmetic checks","Failed documents rejected with the exact reason","Validated records posted as drafts, not final entries"],"integrations":["QuickBooks","Xero","Email inbox","Google Drive"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"approval"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["extraction","accounts-payable"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('lead-scoring', 'Lead Scoring App', 'STRICT', 'crm-sales', 'Scores inbound leads against your ideal-customer definition with a typed, explainable result for every lead.', 'CONFIGURABLE', true, '{"slug":"lead-scoring","name":"Lead Scoring App","family":"STRICT","foundation":"crm-sales","summary":"Scores inbound leads against your ideal-customer definition with a typed, explainable result for every lead.","description":"Each lead receives a score, a tier and the specific evidence behind it, in a fixed schema your CRM can rely on. Leads with missing or contradictory information are routed for review instead of being scored on a guess. Scores are written to your CRM; outreach is left to your team or a separate approved workflow.","outcomes":["Score, tier and evidence for every inbound lead","Incomplete leads routed to review, not guessed","Consistent fields your CRM automations can trust"],"integrations":["HubSpot","Salesforce","Webhooks"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["scoring","inbound"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('ticket-classifier', 'Ticket Classifier', 'STRICT', 'support', 'Classifies every support ticket by topic, urgency and product area into a fixed taxonomy your team controls.', 'CONFIGURABLE', true, '{"slug":"ticket-classifier","name":"Ticket Classifier","family":"STRICT","foundation":"support","summary":"Classifies every support ticket by topic, urgency and product area into a fixed taxonomy your team controls.","description":"Tickets are classified into your taxonomy with a confidence value; low-confidence results go to a person instead of a default bucket. Taxonomy changes are versioned so reports stay comparable. The app only reads tickets and writes classification fields.","outcomes":["Consistent topic, urgency and product-area tags","Low-confidence tickets routed to a person","Versioned taxonomy for comparable reporting"],"integrations":["Zendesk","Freshdesk","Intercom","Jira Service Management"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["classification","routing"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('inventory-reconciler', 'Inventory Reconciler', 'STRICT', 'commerce-inventory', 'Reconciles stock counts across your store, warehouse and marketplaces and explains every discrepancy it finds.', 'CONFIGURABLE', true, '{"slug":"inventory-reconciler","name":"Inventory Reconciler","family":"STRICT","foundation":"commerce-inventory","summary":"Reconciles stock counts across your store, warehouse and marketplaces and explains every discrepancy it finds.","description":"The reconciler reads stock positions from each system, normalises SKUs and units, and produces a typed discrepancy report with likely causes. Proposed adjustments are drafts; applying an adjustment to a system of record requires approval.","outcomes":["Stock positions reconciled across every channel","Discrepancies explained with likely causes","Adjustments applied only after approval"],"integrations":["Shopify","Amazon Seller Central","NetSuite","ShipBob"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["inventory","reconciliation"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('contract-clause-extractor', 'Contract Clause Extractor', 'STRICT', 'operations', 'Extracts parties, dates, renewal terms and key clauses from agreements into a register you can search and report on.', 'CONFIGURABLE', true, '{"slug":"contract-clause-extractor","name":"Contract Clause Extractor","family":"STRICT","foundation":"operations","summary":"Extracts parties, dates, renewal terms and key clauses from agreements into a register you can search and report on.","description":"Agreements are parsed into a strict contract record: parties, effective and renewal dates, notice periods, liability caps and other clauses you define. Each field links to the passage it came from, and missing fields are reported rather than invented. The register flags renewals ahead of their notice deadlines.","outcomes":["A searchable contract register with linked passages","Missing terms reported, never invented","Renewal and notice deadlines flagged in advance"],"integrations":["DocuSign","Google Drive","SharePoint","Box"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["local-first","customer-provider","maximum-intelligence"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["contracts","register"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('catalog-normalizer', 'Product Catalog Normalizer', 'STRICT', 'commerce-inventory', 'Cleans supplier product feeds into one validated catalog schema: attributes, units, categories and variants.', 'CONFIGURABLE', true, '{"slug":"catalog-normalizer","name":"Product Catalog Normalizer","family":"STRICT","foundation":"commerce-inventory","summary":"Cleans supplier product feeds into one validated catalog schema: attributes, units, categories and variants.","description":"Supplier feeds arrive in every shape. The normalizer maps each one into your catalog schema, standardises units and attribute values, assigns categories and groups variants. Rows that cannot be mapped confidently are held for review. Publishing the normalised catalog to your store is approval-gated.","outcomes":["Supplier feeds mapped to one catalog schema","Units, attributes and variants standardised","Unmappable rows held for review"],"integrations":["CSV/SFTP feeds","Shopify","Akeneo","Google Merchant Center"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["pim","feeds"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('provisioning-spec-validator', 'Provisioning Spec Validator', 'STRICT', 'developer-builder', 'Checks infrastructure and environment requests against typed policies before anything is created.', 'CONFIGURABLE', true, '{"slug":"provisioning-spec-validator","name":"Provisioning Spec Validator","family":"STRICT","foundation":"developer-builder","summary":"Checks infrastructure and environment requests against typed policies before anything is created.","description":"Environment and infrastructure requests are parsed into a typed specification and checked against your policies: allowed regions, sizes, network exposure, secret references rather than inline secrets, and required tags. Violations are returned with the rule that failed. The validator never provisions anything itself.","outcomes":["Requests checked against typed infrastructure policies","Inline secrets and public exposure rejected with reasons","No provisioning side effects — validation only"],"integrations":["Terraform plans","GitHub","Kubernetes manifests"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"DEPLOY","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["policy-as-code","infrastructure"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('form-intake', 'Form & Document Intake', 'STRICT', 'operations', 'Turns emailed forms, PDFs and scans into validated records in your systems, with a person reviewing exceptions.', 'CONFIGURABLE', true, '{"slug":"form-intake","name":"Form & Document Intake","family":"STRICT","foundation":"operations","summary":"Turns emailed forms, PDFs and scans into validated records in your systems, with a person reviewing exceptions.","description":"Applications, claims, registrations and other forms arrive by email or upload. The intake app extracts them into your schema, validates required fields and formats, and writes valid records to your system. Attachments are scanned and treated as untrusted; exceptions go to a review queue with the reason.","outcomes":["Forms and scans turned into validated records","Exceptions queued for review with the reason","Attachments scanned and handled as untrusted input"],"integrations":["Email inbox","Google Drive","Airtable","Salesforce"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["documents","extraction"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('expense-policy-checker', 'Expense Policy Checker', 'STRICT', 'finance-admin', 'Checks every expense claim against your written policy and returns a typed pass, fail or needs-review result.', 'CONFIGURABLE', true, '{"slug":"expense-policy-checker","name":"Expense Policy Checker","family":"STRICT","foundation":"finance-admin","summary":"Checks every expense claim against your written policy and returns a typed pass, fail or needs-review result.","description":"Expense claims and receipts are validated against your policy rules — limits, categories, required approvals and receipts. Each claim receives a structured verdict with the rule that applied. Reimbursement remains in your finance system and requires its normal approval.","outcomes":["Structured verdict for every claim with the rule applied","Missing receipts and over-limit items flagged","Reimbursement left to your normal approval process"],"integrations":["Expensify","Ramp","Brex","QuickBooks"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["expenses","policy"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('call-summary', 'Call Summary App', 'STRICT', 'voice-reception', 'Turns call recordings or transcripts into typed notes: caller, reason, outcome, follow-ups and consent status.', 'CONFIGURABLE', true, '{"slug":"call-summary","name":"Call Summary App","family":"STRICT","foundation":"voice-reception","summary":"Turns call recordings or transcripts into typed notes: caller, reason, outcome, follow-ups and consent status.","description":"Each call becomes a structured note with the caller, the reason for the call, what was agreed and any follow-ups with owners. Recording consent is captured as a field, and calls without it are not processed. Notes are written to your CRM or ticketing system.","outcomes":["Structured notes for every call","Follow-ups with owners and dates","Calls without recorded consent skipped"],"integrations":["Twilio","Aircall","HubSpot","Zendesk"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["local-first","lowest-cost"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["calls","notes"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('cited-answers', 'Cited Answers App', 'STRICT', 'knowledge-memory', 'Answers questions from your documents only when it can cite them — otherwise it says it does not know.', 'CONFIGURABLE', true, '{"slug":"cited-answers","name":"Cited Answers App","family":"STRICT","foundation":"knowledge-memory","summary":"Answers questions from your documents only when it can cite them — otherwise it says it does not know.","description":"Every answer must pass a citation contract: each statement references a passage from your approved sources. If the contract cannot be met, the app says so rather than answering from general knowledge. Retrieved documents are treated as untrusted data, never as instructions.","outcomes":["Answers that cite a specific passage for each statement","Explicit ''not found'' instead of unsupported answers","Only approved sources are searched"],"integrations":["SharePoint","Confluence","Google Drive","Notion"],"actions":[{"action":"READ","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["q-and-a","citations"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('quiz-generator', 'Quiz Generator', 'STRICT', 'learning-maker', 'Generates quizzes from your material with a validated answer key and a source reference for every question.', 'CONFIGURABLE', true, '{"slug":"quiz-generator","name":"Quiz Generator","family":"STRICT","foundation":"learning-maker","summary":"Generates quizzes from your material with a validated answer key and a source reference for every question.","description":"The quiz generator creates multiple-choice, short-answer and worked-problem questions from your lessons. Every question has a validated answer key and a link to the source passage, and distractors are checked not to be accidentally correct. Teachers review before quizzes are shared with learners.","outcomes":["Quizzes with validated answer keys","A source reference for every question","Teacher review before sharing"],"integrations":["Google Classroom","Canvas","Moodle","PDF"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["local-first","lowest-cost","balanced"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["education","assessment"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('work-order-validator', 'Work Order Validator', 'STRICT', 'operations', 'Validates manufacturing and maintenance work orders against specifications before they reach the floor.', 'CONFIGURABLE', true, '{"slug":"work-order-validator","name":"Work Order Validator","family":"STRICT","foundation":"operations","summary":"Validates manufacturing and maintenance work orders against specifications before they reach the floor.","description":"Work orders are parsed into a typed record and checked against the bill of materials, routing, tolerances and safety requirements. Invalid orders are returned with the failed rule; valid ones are released to your planning system as drafts for a supervisor to confirm.","outcomes":["Work orders checked against specs and safety rules","Failed checks returned with the rule that failed","Release to the floor confirmed by a supervisor"],"integrations":["SAP","Odoo","Fiix","Google Sheets"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"pydanticai","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu","gpu-24gb"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["manufacturing","maintenance"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('front-desk-kiosk', 'Front Desk Kiosk', 'EDGE', 'voice-reception', 'A check-in and wayfinding assistant that runs on a kiosk in your lobby, with models running on the device.', 'CUSTOM', true, '{"slug":"front-desk-kiosk","name":"Front Desk Kiosk","family":"EDGE","foundation":"voice-reception","summary":"A check-in and wayfinding assistant that runs on a kiosk in your lobby, with models running on the device.","description":"The Front Desk Kiosk greets visitors, handles check-in against the day''s appointments, answers common questions from your approved information and notifies the host. It runs locally on the kiosk hardware so visitor details stay on site. It cannot send messages outside your organisation.","outcomes":["Visitor check-in against the day''s appointments","Answers limited to your approved information","Visitor data kept on the device"],"integrations":["Local calendar sync","Slack","Microsoft Teams"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["kiosk","check-in"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('store-counter-assistant', 'Store Counter Assistant', 'EDGE', 'commerce-inventory', 'Helps staff look up stock, product details and store policy at the counter — on a small in-store box.', 'CUSTOM', true, '{"slug":"store-counter-assistant","name":"Store Counter Assistant","family":"EDGE","foundation":"commerce-inventory","summary":"Helps staff look up stock, product details and store policy at the counter — on a small in-store box.","description":"Store staff ask about stock levels, product details, alternatives and store policy; the assistant answers from your synced catalog and policy documents. It runs on an in-store device, continues to answer from its last sync if the internet drops, and has read-only access to your systems.","outcomes":["Stock and product answers at the counter","Keeps working from the last sync when offline","Read-only access to store systems"],"integrations":["Shopify POS","Square","Lightspeed"],"actions":[{"action":"READ","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["retail","offline"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('field-notes-offline', 'Offline Field Notes', 'EDGE', 'operations', 'A field technician''s assistant that works without signal: checklists, notes and photos turned into reports.', 'CUSTOM', true, '{"slug":"field-notes-offline","name":"Offline Field Notes","family":"EDGE","foundation":"operations","summary":"A field technician''s assistant that works without signal: checklists, notes and photos turned into reports.","description":"Technicians dictate or type notes and follow checklists on a rugged laptop or tablet. The assistant structures them into a job report on the device and queues the report for sync when a connection returns. Nothing is uploaded until the technician confirms the report.","outcomes":["Job reports assembled on the device, without signal","Checklists followed step by step","Upload only after the technician confirms"],"integrations":["Job management export","CSV","Photo library"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["field-service","offline"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('local-document-search', 'Local Document Search', 'EDGE', 'knowledge-memory', 'Ask questions of a folder of documents on your own machine — nothing is uploaded anywhere.', 'CUSTOM', true, '{"slug":"local-document-search","name":"Local Document Search","family":"EDGE","foundation":"knowledge-memory","summary":"Ask questions of a folder of documents on your own machine — nothing is uploaded anywhere.","description":"Point it at a folder and it indexes the documents locally, then answers questions with references to the files and passages used. The index and the models live on your machine. File access is limited to the folders you choose, and links that escape those folders are refused.","outcomes":["Answers with references to local files and passages","Index and models stay on your machine","Access limited to the folders you choose"],"integrations":["Local folders","PDF","Markdown","Office documents"],"actions":[{"action":"READ","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"DELETE","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","unified-memory-node"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["private","search"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('home-hub', 'Home Hub', 'EDGE', 'family-play', 'A household assistant on a small home server: family calendar, reminders and homework help that stays at home.', 'CUSTOM', true, '{"slug":"home-hub","name":"Home Hub","family":"EDGE","foundation":"family-play","summary":"A household assistant on a small home server: family calendar, reminders and homework help that stays at home.","description":"Home Hub runs on a small computer in your home. It keeps the family calendar and reminders, helps with homework at an age-appropriate level and answers household questions from your own notes. Guardians control each profile. It has no purchasing ability and no public sharing.","outcomes":["Family calendar and reminders kept at home","Homework help with guardian-set limits","No purchasing and no public sharing"],"integrations":["Calendar sync","Local notes"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["home","family","guardian"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('maker-bench', 'Maker Bench Assistant', 'EDGE', 'learning-maker', 'A workshop helper on a single-board computer: project steps, parts lists and troubleshooting at the bench.', 'CUSTOM', true, '{"slug":"maker-bench","name":"Maker Bench Assistant","family":"EDGE","foundation":"learning-maker","summary":"A workshop helper on a single-board computer: project steps, parts lists and troubleshooting at the bench.","description":"Maker Bench walks you through builds step by step, keeps parts lists and wiring notes per project and helps troubleshoot from your own photos and notes. It runs on a single-board computer or an old laptop at the bench, and works offline once your project files are loaded.","outcomes":["Step-by-step build guidance per project","Parts lists and wiring notes kept together","Works offline at the bench"],"integrations":["Local project folders","Markdown","Photos"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["maker","workshop"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('classroom-tutor', 'Classroom Tutor Station', 'EDGE', 'learning-maker', 'A tutor that runs on school-owned hardware, keeping student questions and progress inside the school.', 'CUSTOM', true, '{"slug":"classroom-tutor","name":"Classroom Tutor Station","family":"EDGE","foundation":"learning-maker","summary":"A tutor that runs on school-owned hardware, keeping student questions and progress inside the school.","description":"Classroom Tutor Station runs on hardware the school owns. Students ask questions and practise with guidance aligned to the teacher''s lesson materials; teachers see progress and set boundaries. Student data does not leave the school''s network.","outcomes":["Practice aligned to the teacher''s materials","Progress visible to the teacher","Student data kept on the school network"],"integrations":["Local lesson library","Google Classroom export"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"PUBLISH","rule":"draft-only"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","unified-memory-node"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["education","on-prem"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('local-reception-line', 'Local Reception Line', 'EDGE', 'voice-reception', 'Answers your phone line from a box in your office: takes messages, books from open slots and hands off to a person.', 'CUSTOM', true, '{"slug":"local-reception-line","name":"Local Reception Line","family":"EDGE","foundation":"voice-reception","summary":"Answers your phone line from a box in your office: takes messages, books from open slots and hands off to a person.","description":"Local Reception Line answers calls, takes structured messages, books appointments into open slots you define and transfers to a person on request or when unsure. Speech processing runs on your hardware. It follows your script and cannot make outbound calls.","outcomes":["Calls answered and messages captured in a structured form","Bookings only into open slots you define","Transfer to a person on request or when unsure"],"integrations":["SIP phone system","Local calendar","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","unified-memory-node"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["phone","reception"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('equipment-log-watcher', 'Equipment Log Watcher', 'EDGE', 'operations', 'Reads machine and sensor logs on site, summarises what changed and raises alerts in plain language.', 'CUSTOM', true, '{"slug":"equipment-log-watcher","name":"Equipment Log Watcher","family":"EDGE","foundation":"operations","summary":"Reads machine and sensor logs on site, summarises what changed and raises alerts in plain language.","description":"The watcher reads equipment and sensor logs on a local device, summarises shifts in behaviour and raises plain-language alerts to the people on duty. It has read-only access to logs and cannot change equipment settings. Alerts and summaries stay on the local network unless you enable forwarding.","outcomes":["Plain-language summaries of equipment behaviour","Alerts routed to the people on duty","Read-only: no access to equipment settings"],"integrations":["Syslog","MQTT","CSV exports"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"DEPLOY","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["monitoring","industrial"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('private-daily-brief', 'Private Daily Brief', 'EDGE', 'chief', 'A personal morning brief built on your own laptop from your calendar, notes and tasks — nothing leaves the device.', 'CUSTOM', true, '{"slug":"private-daily-brief","name":"Private Daily Brief","family":"EDGE","foundation":"chief","summary":"A personal morning brief built on your own laptop from your calendar, notes and tasks — nothing leaves the device.","description":"Private Daily Brief reads your local calendar, notes and task files and writes a short brief each morning: what is due, what changed and what to prepare. The models run on your laptop. It has no send capability and works only with the folders and calendars you grant.","outcomes":["A morning brief assembled on your own device","Only granted folders and calendars are read","No outbound sending capability"],"integrations":["Local calendar","Markdown notes","Task files"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["personal","private"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('local-code-helper', 'Local Code Helper', 'EDGE', 'developer-builder', 'A coding helper that runs on your workstation against local repositories, for code that must not leave the machine.', 'CUSTOM', true, '{"slug":"local-code-helper","name":"Local Code Helper","family":"EDGE","foundation":"developer-builder","summary":"A coding helper that runs on your workstation against local repositories, for code that must not leave the machine.","description":"Local Code Helper explains code, drafts changes and writes tests against repositories on your machine, using local models. It works inside the repository you open, refuses paths outside it and runs only the commands on your allowlist. Pushing and publishing are yours to do.","outcomes":["Code explanations and drafts without uploading code","Access confined to the open repository","Commands limited to your allowlist"],"integrations":["Git","Local editor","Test runner"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"draft-only"},{"action":"DEPLOY","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","unified-memory-node","gpu-24gb"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["code","private"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('shop-floor-assistant', 'Shop Floor Assistant', 'EDGE', 'operations', 'Answers procedure and safety questions on the shop floor from your own manuals, on hardware you control.', 'CUSTOM', true, '{"slug":"shop-floor-assistant","name":"Shop Floor Assistant","family":"EDGE","foundation":"operations","summary":"Answers procedure and safety questions on the shop floor from your own manuals, on hardware you control.","description":"Operators ask how to perform a procedure, what a warning means or which part fits; the assistant answers from your manuals and work instructions with references. It runs on a local server or panel PC, works through network outages and has no ability to change machine settings.","outcomes":["Procedure and safety answers from your own manuals","References to the exact instruction used","Works through network outages"],"integrations":["Manual library","Work instructions","Local wiki"],"actions":[{"action":"READ","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"DEPLOY","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","unified-memory-node"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["manufacturing","manuals"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('small-office-help-desk', 'Small Office Help Desk', 'EDGE', 'support', 'An IT help desk for a small office on a local box: password-reset guidance, printer fixes and ticket drafts.', 'CUSTOM', true, '{"slug":"small-office-help-desk","name":"Small Office Help Desk","family":"EDGE","foundation":"support","summary":"An IT help desk for a small office on a local box: password-reset guidance, printer fixes and ticket drafts.","description":"Staff ask for help with common IT problems and get step-by-step guidance from your own procedures. Anything it cannot solve becomes a drafted ticket for your IT provider. It has no administrative access to accounts or devices; resets and changes are done by a person.","outcomes":["Step-by-step fixes from your own procedures","Unresolved issues drafted as tickets","No administrative access to accounts or devices"],"integrations":["Local procedures","Email","Ticket export"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"zeroclaw","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","cpu"],"deployments":["edge-device","on-prem"],"maturity":"CUSTOM","tags":["it-support","small-business"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('private-workspace', 'Private Assistant Workspace', 'SECURE', 'chief', 'A governed assistant workspace deployed in your own cloud account, with your keys, logs and approvals.', 'CUSTOM', true, '{"slug":"private-workspace","name":"Private Assistant Workspace","family":"SECURE","foundation":"chief","summary":"A governed assistant workspace deployed in your own cloud account, with your keys, logs and approvals.","description":"The Private Assistant Workspace runs in a cell inside your cloud account. Identity comes from your provider, secrets stay in your vault and are referenced rather than copied, logs go to your logging stack and every consequential action is approval-gated. Acceptance covers isolation, secrets handling and audit before go-live.","outcomes":["An assistant workspace inside your own cloud boundary","Secrets referenced from your vault, never copied into prompts","Isolation and audit accepted before go-live"],"integrations":["Microsoft Entra ID","Okta","AWS","Azure","Google Cloud"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["private-cloud","sso"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('air-gapped-assistant', 'Air-Gapped Assistant', 'SECURE', 'knowledge-memory', 'A knowledge assistant for networks with no internet connection: local models, local index, offline updates.', 'CUSTOM', true, '{"slug":"air-gapped-assistant","name":"Air-Gapped Assistant","family":"SECURE","foundation":"knowledge-memory","summary":"A knowledge assistant for networks with no internet connection: local models, local index, offline updates.","description":"For environments with no outbound connectivity, the Air-Gapped Assistant runs entirely on your hardware: local models, a local document index and an offline update process with verifiable packages. Any request that would need an external service fails closed. Acceptance is performed on site against your requirements.","outcomes":["Question answering with no external connectivity","Offline, verifiable update packages","External calls fail closed by design"],"integrations":["Local file shares","On-prem document stores"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"DEPLOY","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-only"],"compute":["unified-memory-node","gpu-80-96gb","gpu-128gb-plus"],"deployments":["on-prem"],"maturity":"CUSTOM","tags":["air-gapped","offline"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('regulated-support', 'Regulated Support Desk', 'SECURE', 'support', 'Support drafting for regulated industries: personal data stays in your boundary and every reply is reviewed.', 'CUSTOM', true, '{"slug":"regulated-support","name":"Regulated Support Desk","family":"SECURE","foundation":"support","summary":"Support drafting for regulated industries: personal data stays in your boundary and every reply is reviewed.","description":"The Regulated Support Desk drafts replies from your approved knowledge inside your environment. Personal data is minimised in prompts, every reply is reviewed by an agent before sending, and a complete audit trail is kept in your systems. Retention and deletion follow your policies.","outcomes":["Reply drafts generated inside your boundary","Every reply reviewed before sending","Audit trail and retention under your control"],"integrations":["Zendesk","Salesforce Service Cloud","ServiceNow"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["regulated","support"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('clinical-admin', 'Clinical Admin Assistant', 'SECURE', 'operations', 'Administrative support for clinics — scheduling, referrals and paperwork — deployed privately. No clinical advice.', 'CUSTOM', true, '{"slug":"clinical-admin","name":"Clinical Admin Assistant","family":"SECURE","foundation":"operations","summary":"Administrative support for clinics — scheduling, referrals and paperwork — deployed privately. No clinical advice.","description":"The Clinical Admin Assistant handles administrative work: scheduling requests, referral paperwork, form completion and document routing. It is explicitly scoped away from diagnosis or treatment advice. Deployment is private, access follows your roles and every outbound message is approval-gated.","outcomes":["Scheduling and referral paperwork prepared","Explicitly no diagnosis or treatment advice","Outbound messages approved by staff"],"integrations":["EHR export","Fax/email gateway","Calendar"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["healthcare-admin","private"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('matter-workspace', 'Matter Workspace', 'SECURE', 'research', 'A private research workspace per legal matter, with walls between matters and citations to your documents.', 'CUSTOM', true, '{"slug":"matter-workspace","name":"Matter Workspace","family":"SECURE","foundation":"research","summary":"A private research workspace per legal matter, with walls between matters and citations to your documents.","description":"Each matter gets its own isolated workspace: documents, research notes and drafts do not cross between matters. The assistant researches and drafts with citations to your documents, and conflicts between matters are prevented by isolation rather than by instructions.","outcomes":["One isolated workspace per matter","Research and drafts cited to your documents","No data crossing between matters"],"integrations":["iManage","NetDocuments","SharePoint"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["legal","isolation"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('finance-controls', 'Finance Controls Assistant', 'SECURE', 'finance-admin', 'Monitors transactions against your controls inside your environment and prepares exceptions for review.', 'CUSTOM', true, '{"slug":"finance-controls","name":"Finance Controls Assistant","family":"SECURE","foundation":"finance-admin","summary":"Monitors transactions against your controls inside your environment and prepares exceptions for review.","description":"The Finance Controls Assistant checks journal entries, payments and vendor changes against your control rules and prepares exception reports with evidence. It has read access to finance data, no ability to move money, and runs inside your environment with logs in your systems.","outcomes":["Transactions checked against your control rules","Exception reports with supporting evidence","No ability to move money"],"integrations":["SAP","Oracle NetSuite","Workday","Snowflake"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["controls","finance"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('secure-code-assistant', 'Secure Code Assistant', 'SECURE', 'developer-builder', 'A coding assistant deployed in your environment for proprietary code, with no code leaving your boundary.', 'CUSTOM', true, '{"slug":"secure-code-assistant","name":"Secure Code Assistant","family":"SECURE","foundation":"developer-builder","summary":"A coding assistant deployed in your environment for proprietary code, with no code leaving your boundary.","description":"The Secure Code Assistant runs inside your network against your repositories. Models run locally or through your own provider account. It works in isolated workspaces with command allowlists, and merges, releases and deployments remain approval-gated.","outcomes":["Code assistance without code leaving your boundary","Isolated workspaces with command allowlists","Merges and deployments approval-gated"],"integrations":["GitHub Enterprise","GitLab self-managed","Bitbucket Data Center"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"DEPLOY","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["gpu-48gb","gpu-80-96gb","gpu-128gb-plus"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["code","private"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('private-sales-desk', 'Private Sales Desk', 'SECURE', 'crm-sales', 'Sales assistance for firms whose client data cannot leave their environment — CRM hygiene and drafted outreach.', 'CUSTOM', true, '{"slug":"private-sales-desk","name":"Private Sales Desk","family":"SECURE","foundation":"crm-sales","summary":"Sales assistance for firms whose client data cannot leave their environment — CRM hygiene and drafted outreach.","description":"The Private Sales Desk keeps client records current and drafts outreach inside your environment. Client data stays in your systems, outreach is approved before sending, and suppression and consent rules are enforced before any draft is created.","outcomes":["CRM hygiene without client data leaving your boundary","Consent and suppression checked before drafting","Outreach approved before sending"],"integrations":["Salesforce","Microsoft Dynamics","Outlook"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["crm","private"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('compliance-copilot', 'Compliance Assistant', 'SECURE', 'security-compliance', 'Answers policy questions and prepares control evidence inside your environment, with every answer cited.', 'CUSTOM', true, '{"slug":"compliance-copilot","name":"Compliance Assistant","family":"SECURE","foundation":"security-compliance","summary":"Answers policy questions and prepares control evidence inside your environment, with every answer cited.","description":"Staff ask what a policy requires and receive answers cited to the policy text. For compliance teams, the assistant prepares evidence packages and drafts control narratives for review. It makes no certification claims and runs within your boundary.","outcomes":["Policy answers cited to the policy text","Evidence packages and control narratives drafted","No certification claims — preparation only"],"integrations":["SharePoint","Confluence","ServiceNow GRC"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["policy","evidence"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('private-voice-reception', 'Private Voice Reception', 'SECURE', 'voice-reception', 'Call answering where recordings and transcripts must stay on your infrastructure.', 'CUSTOM', true, '{"slug":"private-voice-reception","name":"Private Voice Reception","family":"SECURE","foundation":"voice-reception","summary":"Call answering where recordings and transcripts must stay on your infrastructure.","description":"Private Voice Reception answers and routes calls, takes structured messages and books into open slots, with speech processing and storage on your infrastructure. Recording consent is captured, retention follows your policy and transfers to a person are always available.","outcomes":["Calls answered with audio kept on your infrastructure","Consent captured and retention enforced","Transfer to a person always available"],"integrations":["SIP trunk","Microsoft Teams Phone","Calendar"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"nemoclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["voice","private"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('research-enclave', 'Research Enclave', 'SECURE', 'research', 'A sealed research environment for sensitive datasets: analysis in place, only approved outputs leave.', 'CUSTOM', true, '{"slug":"research-enclave","name":"Research Enclave","family":"SECURE","foundation":"research","summary":"A sealed research environment for sensitive datasets: analysis in place, only approved outputs leave.","description":"The Research Enclave brings analysis to your data instead of moving data out. Researchers work in isolated sessions, outputs are checked against disclosure rules and only approved outputs can leave the enclave. Every session is logged.","outcomes":["Analysis performed where the data lives","Outputs checked against disclosure rules","Only approved outputs leave the enclave"],"integrations":["Snowflake","Databricks","S3-compatible storage"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"PUBLISH","rule":"approval"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"nemoclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["gpu-80-96gb","gpu-128gb-plus","gpu-141gb-plus"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["data","disclosure-control"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('board-pack', 'Board Pack Preparer', 'SECURE', 'chief', 'Assembles board and committee packs from management reports, privately, with a change log between drafts.', 'CUSTOM', true, '{"slug":"board-pack","name":"Board Pack Preparer","family":"SECURE","foundation":"chief","summary":"Assembles board and committee packs from management reports, privately, with a change log between drafts.","description":"The Board Pack Preparer gathers management reports, drafts summaries and assembles the pack in your template, keeping a change log between drafts. Distribution to directors is approval-gated, and material stays inside your environment throughout.","outcomes":["Board packs assembled in your template","A change log between each draft","Distribution only after approval"],"integrations":["SharePoint","Diligent export","Google Drive"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SEND_EXTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["governance","reporting"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('sovereign-knowledge-base', 'Sovereign Knowledge Base', 'SECURE', 'knowledge-memory', 'Organisational memory hosted in your jurisdiction and infrastructure, with provenance and corrections preserved.', 'CUSTOM', true, '{"slug":"sovereign-knowledge-base","name":"Sovereign Knowledge Base","family":"SECURE","foundation":"knowledge-memory","summary":"Organisational memory hosted in your jurisdiction and infrastructure, with provenance and corrections preserved.","description":"The Sovereign Knowledge Base keeps organisational memory in the region and infrastructure you choose. Every entry records its source and author, corrections are versioned, and export and deletion are available at any time. Model calls follow your chosen local or customer-provider policy.","outcomes":["Memory hosted in your chosen jurisdiction","Provenance and versioned corrections on every entry","Export and deletion on demand"],"integrations":["Confluence Data Center","SharePoint","S3-compatible storage"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"openclaw","modelPolicies":["local-first","customer-provider","local-only"],"compute":["unified-memory-node","gpu-48gb","gpu-80-96gb"],"deployments":["private-cloud","on-prem"],"maturity":"CUSTOM","tags":["sovereignty","memory"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('architecture-advisor', 'Architecture Advisor', 'AUTO', 'developer-builder', 'Maps your requirements to the right kind of AI system and explains every choice it makes.', 'CONFIGURABLE', true, '{"slug":"architecture-advisor","name":"Architecture Advisor","family":"AUTO","foundation":"developer-builder","summary":"Maps your requirements to the right kind of AI system and explains every choice it makes.","description":"Answer eleven questions — conversation, explicit states, teams, strict outputs, edge hardware, privacy, governance, latency, budget, concurrency and approvals — and the Architecture Advisor recommends a system family, deployment, model policy and compute class. The recommendation is deterministic and each decision carries the reason behind it.","outcomes":["A recommended system shape from eleven questions","A reason attached to every decision","The same inputs always give the same answer"],"integrations":["Configurator","Export to PDF"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["recommendation","architecture"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('model-router', 'Model Router', 'AUTO', 'developer-builder', 'Routes each step to local, your-provider or managed models under the policy you choose — never a silent paid fallback.', 'CONFIGURABLE', true, '{"slug":"model-router","name":"Model Router","family":"AUTO","foundation":"developer-builder","summary":"Routes each step to local, your-provider or managed models under the policy you choose — never a silent paid fallback.","description":"The Model Router applies your model policy per step: local only, local first, your provider, managed, balanced, maximum intelligence or lowest cost. When a route is unavailable it fails or asks for approval according to policy; it never silently switches to a paid route. Every routing decision is logged with its cost estimate.","outcomes":["Per-step routing under an explicit model policy","No silent fallback to paid routes","Routing decisions logged with cost estimates"],"integrations":["Local model server","Your provider account","Managed providers"],"actions":[{"action":"READ","rule":"allow"},{"action":"SPEND","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["routing","cost-control"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('compute-planner', 'Compute Planner', 'AUTO', 'operations', 'Sizes the compute class for your workload from concurrency and model needs, and shows the trade-offs.', 'CONFIGURABLE', true, '{"slug":"compute-planner","name":"Compute Planner","family":"AUTO","foundation":"operations","summary":"Sizes the compute class for your workload from concurrency and model needs, and shows the trade-offs.","description":"The Compute Planner takes your expected users, workloads and model policy and proposes a compute class — from CPU through unified-memory nodes to large GPU classes — with the trade-offs of the options either side. Cloud burst is planned by compute time, not by model file size.","outcomes":["A proposed compute class with alternatives","Trade-offs shown for the options either side","Burst planned by compute time"],"integrations":["Configurator","Usage exports"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["capacity","sizing"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('cost-guard', 'Cost Guard', 'AUTO', 'finance-admin', 'Daily model-cost and compute ceilings per system, with alerts before limits and hard stops at them.', 'CONFIGURABLE', true, '{"slug":"cost-guard","name":"Cost Guard","family":"AUTO","foundation":"finance-admin","summary":"Daily model-cost and compute ceilings per system, with alerts before limits and hard stops at them.","description":"Cost Guard tracks estimated model and compute spend per system and per day. It alerts at thresholds you set and stops further paid calls at the ceiling until an owner approves more. Estimates and actuals are reconciled so you can see where forecasts were wrong.","outcomes":["Per-system daily cost ceilings","Alerts before limits, hard stops at limits","Estimates reconciled with actuals"],"integrations":["Usage exports","Slack","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SPEND","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["budgets","limits"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('local-first-planner', 'Local-First Planner', 'AUTO', 'knowledge-memory', 'Identifies which steps of your system can run on local models and what that means for privacy and cost.', 'CONFIGURABLE', true, '{"slug":"local-first-planner","name":"Local-First Planner","family":"AUTO","foundation":"knowledge-memory","summary":"Identifies which steps of your system can run on local models and what that means for privacy and cost.","description":"The Local-First Planner reviews each step of a proposed system and marks which can run on local models, which need more capable routes and why. It estimates the privacy and cost effect of moving steps local and proposes a local-first policy you can adopt step by step.","outcomes":["Each step classified as local-capable or not, with reasons","Privacy and cost effect of moving steps local","A staged local-first adoption plan"],"integrations":["Configurator","Local model server"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","local-only"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["local","privacy"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('provider-comparison', 'Provider Comparison', 'AUTO', 'research', 'Compares model routes on your own evaluation tasks, so choices rest on your data rather than headlines.', 'CONFIGURABLE', true, '{"slug":"provider-comparison","name":"Provider Comparison","family":"AUTO","foundation":"research","summary":"Compares model routes on your own evaluation tasks, so choices rest on your data rather than headlines.","description":"Provider Comparison runs your evaluation set across the routes you are considering and reports quality, cost and latency on your tasks. Results are reproducible, dated and kept with the exact configuration used, so decisions can be revisited when models change.","outcomes":["Quality, cost and latency measured on your tasks","Reproducible, dated results with exact configuration","Decisions revisitable as models change"],"integrations":["Evaluation datasets","Your provider accounts"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"SPEND","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["evaluation","benchmarking"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('capacity-forecaster', 'Capacity Forecaster', 'AUTO', 'operations', 'Forecasts when your systems will need more compute from real usage, with lead time to plan the change.', 'CONFIGURABLE', true, '{"slug":"capacity-forecaster","name":"Capacity Forecaster","family":"AUTO","foundation":"operations","summary":"Forecasts when your systems will need more compute from real usage, with lead time to plan the change.","description":"The Capacity Forecaster reads usage trends per system and projects when the current compute class will run short, with a confidence range. It proposes the change and the lead time needed, and it flags forecasts built on too little history.","outcomes":["Projected capacity shortfalls with confidence ranges","Proposed changes with lead time","Low-history forecasts clearly flagged"],"integrations":["Usage metrics","Slack","Email"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["forecasting","capacity"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('model-migration-planner', 'Model Migration Planner', 'AUTO', 'developer-builder', 'Plans a move between models or providers with side-by-side checks, staged rollout and a rollback path.', 'CONFIGURABLE', true, '{"slug":"model-migration-planner","name":"Model Migration Planner","family":"AUTO","foundation":"developer-builder","summary":"Plans a move between models or providers with side-by-side checks, staged rollout and a rollback path.","description":"When a model is retired or a better option appears, the Migration Planner runs your evaluation set on both routes, highlights regressions and proposes a staged rollout with a rollback path. Switching production routing is an approval-gated deploy action.","outcomes":["Side-by-side checks before any switch","Regressions highlighted per task","Staged rollout with rollback, approval-gated"],"integrations":["Evaluation datasets","Model Router"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"DEPLOY","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["migration","rollout"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('evaluation-bench', 'Evaluation Bench', 'AUTO', 'security-compliance', 'Keeps an evaluation set for each system and re-runs it on every change, blocking regressions from release.', 'CONFIGURABLE', true, '{"slug":"evaluation-bench","name":"Evaluation Bench","family":"AUTO","foundation":"security-compliance","summary":"Keeps an evaluation set for each system and re-runs it on every change, blocking regressions from release.","description":"Evaluation Bench maintains a versioned evaluation set per system — expected behaviours, refusal cases and injection tests — and re-runs it whenever prompts, models or tools change. A regression blocks the release until it is fixed or explicitly accepted by an owner.","outcomes":["Versioned evaluation sets per system","Re-run automatically on every change","Regressions block release until resolved"],"integrations":["CI pipelines","GitHub Actions"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DEPLOY","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["evals","regression"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('budget-planner', 'AI Budget Planner', 'AUTO', 'finance-admin', 'Turns planned systems and usage into a monthly budget range, separating setup, cells, compute and model use.', 'CONFIGURABLE', true, '{"slug":"budget-planner","name":"AI Budget Planner","family":"AUTO","foundation":"finance-admin","summary":"Turns planned systems and usage into a monthly budget range, separating setup, cells, compute and model use.","description":"The Budget Planner converts your planned systems and expected usage into a monthly range, separating one-off setup, per-cell running costs, compute time and model usage by policy. Assumptions are listed so finance can challenge them.","outcomes":["A monthly budget range by cost component","Assumptions listed for review","Scenarios for different model policies"],"integrations":["Spreadsheet export","Configurator"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["budgeting","planning"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('latency-tuner', 'Latency Tuner', 'AUTO', 'developer-builder', 'Finds the slow steps in your systems and proposes routing, caching or compute changes with measured effect.', 'CONFIGURABLE', true, '{"slug":"latency-tuner","name":"Latency Tuner","family":"AUTO","foundation":"developer-builder","summary":"Finds the slow steps in your systems and proposes routing, caching or compute changes with measured effect.","description":"The Latency Tuner traces where time goes in each run — model calls, tools, waits — and proposes changes such as routing a step locally, caching stable context or moving to a different compute class. Proposals include the measured effect on a test run before you adopt them.","outcomes":["Per-step timing for each system","Proposed changes with measured effect","Adoption only after review"],"integrations":["Run traces","Model Router"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"DEPLOY","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["latency","performance"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('deployment-selector', 'Deployment Selector', 'AUTO', 'security-compliance', 'Recommends managed, private-cloud, on-premises or edge deployment from your data and governance requirements.', 'CONFIGURABLE', true, '{"slug":"deployment-selector","name":"Deployment Selector","family":"AUTO","foundation":"security-compliance","summary":"Recommends managed, private-cloud, on-premises or edge deployment from your data and governance requirements.","description":"The Deployment Selector weighs data sensitivity, governance requirements, connectivity and budget and recommends where each system should run. It lists the controls each option requires and flags combinations that cannot be met, such as air-gapped operation with hosted models.","outcomes":["A deployment recommendation per system","Required controls listed for each option","Impossible combinations flagged early"],"integrations":["Configurator"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["lowest-cost","balanced","local-first"],"compute":["cpu"],"deployments":["managed-cell","private-cloud"],"maturity":"CONFIGURABLE","tags":["deployment","governance"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('local-hardware-sizer', 'Local Hardware Sizer', 'AUTO', 'learning-maker', 'Helps you choose hardware for running models at home, in class or at the bench, from what you want to do.', 'CONFIGURABLE', true, '{"slug":"local-hardware-sizer","name":"Local Hardware Sizer","family":"AUTO","foundation":"learning-maker","summary":"Helps you choose hardware for running models at home, in class or at the bench, from what you want to do.","description":"Describe what you want to run locally and how many people will use it; the Hardware Sizer suggests memory and compute classes that fit, what each allows and where the limits are. It makes no vendor performance claims — it explains the trade-offs and lets you test.","outcomes":["Memory and compute classes that fit your plans","Clear explanation of limits and trade-offs","No vendor performance claims"],"integrations":["Configurator"],"actions":[{"action":"READ","rule":"allow"},{"action":"DRAFT","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-only","local-first"],"compute":["customer-hardware","unified-memory-node"],"deployments":["edge-device","on-prem"],"maturity":"CONFIGURABLE","tags":["hardware","local"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('action-firewall', 'Action Firewall', 'SHIELD', 'security-compliance', 'Classifies every action a system can take and enforces an explicit allow, draft-only, approval or deny rule.', 'CONFIGURABLE', true, '{"slug":"action-firewall","name":"Action Firewall","family":"SHIELD","foundation":"security-compliance","summary":"Classifies every action a system can take and enforces an explicit allow, draft-only, approval or deny rule.","description":"Every action is classified — read, draft, internal write, external send, publish, spend, delete, deploy or admin — and each workflow carries an explicit rule for each class. Consequential actions default to approval or deny, and rules cannot be relaxed by content the system reads.","outcomes":["Every action classified before it runs","Explicit rules per workflow and action class","Rules unaffected by instructions in content"],"integrations":["All PRFKT systems"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["policy","enforcement"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('secret-broker', 'Secret Broker', 'SHIELD', 'security-compliance', 'Systems use secret references, never secret values — keys stay out of prompts, memory, logs and browsers.', 'CONFIGURABLE', true, '{"slug":"secret-broker","name":"Secret Broker","family":"SHIELD","foundation":"security-compliance","summary":"Systems use secret references, never secret values — keys stay out of prompts, memory, logs and browsers.","description":"Integrations are connected through the Secret Broker, which hands systems a reference instead of a key. Values are resolved only at the moment of a brokered call and never appear in prompts, memory, markdown, logs or browser storage. Text that looks like a secret is redacted before storage.","outcomes":["References instead of secret values in every system","Automatic redaction of secret-like text","Keys never reach prompts, memory or logs"],"integrations":["Cloud secret managers","OAuth providers"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["secrets","oauth"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('injection-sentinel', 'Injection Sentinel', 'SHIELD', 'security-compliance', 'Treats web pages, email, attachments and tool output as data, and flags content that tries to give orders.', 'CONFIGURABLE', true, '{"slug":"injection-sentinel","name":"Injection Sentinel","family":"SHIELD","foundation":"security-compliance","summary":"Treats web pages, email, attachments and tool output as data, and flags content that tries to give orders.","description":"Injection Sentinel marks every piece of external content with its source and trust level, fences it off from instructions and flags attempts to issue commands, request secrets or change recipients. Flagged content cannot unlock new actions; it can only be reviewed.","outcomes":["External content labelled with source and trust","Instruction-like content flagged for review","No action unlocked by untrusted content"],"integrations":["All PRFKT systems"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["prompt-injection","untrusted-input"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('approval-inbox', 'Approval Inbox', 'SHIELD', 'chief', 'One place to approve or reject what your systems want to do, with the exact content and consequence shown.', 'CONFIGURABLE', true, '{"slug":"approval-inbox","name":"Approval Inbox","family":"SHIELD","foundation":"chief","summary":"One place to approve or reject what your systems want to do, with the exact content and consequence shown.","description":"Every approval request shows the exact draft, recipients, amounts or changes involved and what will happen on approval. Approvals are bound to that exact content: if it changes, a new approval is required. Decisions are recorded with who, when and why.","outcomes":["One inbox for all pending approvals","Approvals bound to the exact content shown","Every decision recorded with who, when and why"],"integrations":["Web","Email notifications","Slack notifications"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["approvals","human-in-the-loop"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('audit-trail', 'Audit Trail', 'SHIELD', 'security-compliance', 'An append-only record of what every system and owner did, with secrets redacted and export on demand.', 'CONFIGURABLE', true, '{"slug":"audit-trail","name":"Audit Trail","family":"SHIELD","foundation":"security-compliance","summary":"An append-only record of what every system and owner did, with secrets redacted and export on demand.","description":"The Audit Trail records runs, actions, approvals and administrative changes in an append-only log with secrets redacted. You can filter it by system, person or action and export it for your own records or auditors.","outcomes":["Append-only record of actions and approvals","Secrets redacted before anything is written","Filter and export on demand"],"integrations":["SIEM export","CSV","JSON"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["audit","logging"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('blast-radius-limits', 'Blast-Radius Limits', 'SHIELD', 'operations', 'Caps on sends per hour, recipients per run, spend per day, tool actions per run, retries and timeouts.', 'CONFIGURABLE', true, '{"slug":"blast-radius-limits","name":"Blast-Radius Limits","family":"SHIELD","foundation":"operations","summary":"Caps on sends per hour, recipients per run, spend per day, tool actions per run, retries and timeouts.","description":"Blast-Radius Limits bound what any system can do even when it behaves unexpectedly: sends per hour, recipients per run, spend and model cost per day, tool actions per run, allowed domains, hosts, paths and commands, delete ceilings, timeouts and retry ceilings. Hitting a limit stops the action and notifies an owner.","outcomes":["Hard caps on volume, spend and scope","Allowlists for domains, hosts, paths and commands","Owners notified when a limit is hit"],"integrations":["All PRFKT systems"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["limits","safety"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('red-claw-suite', 'RED CLAW Test Suite', 'SHIELD', 'security-compliance', 'Adversarial tests run against each system: injection, secret extraction, escalation, cross-tenant access and more.', 'CONFIGURABLE', true, '{"slug":"red-claw-suite","name":"RED CLAW Test Suite","family":"SHIELD","foundation":"security-compliance","summary":"Adversarial tests run against each system: injection, secret extraction, escalation, cross-tenant access and more.","description":"RED CLAW exercises each system with adversarial cases: direct and indirect prompt injection, secret extraction, path traversal and symlink escape, command injection, SSRF, tool escalation, cross-tenant access, malicious attachments, duplicate webhooks, unauthorised sending, spending, deleting and deploying, and runaway loops. A critical failure blocks a system from being labelled READY.","outcomes":["Adversarial coverage across sixteen attack categories","Critical failures block READY","Results kept as evidence with each release"],"integrations":["CI pipelines"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DEPLOY","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["adversarial","testing"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('tenant-isolation-review', 'Tenant Isolation Review', 'SHIELD', 'security-compliance', 'Verifies that each customer runs in its own cell and that no data or action crosses between customers.', 'CONFIGURABLE', true, '{"slug":"tenant-isolation-review","name":"Tenant Isolation Review","family":"SHIELD","foundation":"security-compliance","summary":"Verifies that each customer runs in its own cell and that no data or action crosses between customers.","description":"The isolation review checks that every customer has its own runtime cell, that database policies prevent reading another customer''s records and that no shared gateway is treated as a security boundary. Results are recorded as release-gate evidence.","outcomes":["One runtime cell per customer verified","Cross-customer data access tested and blocked","Results recorded as release evidence"],"integrations":["Control plane"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["isolation","multi-tenant"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('data-export-deletion', 'Data Export & Deletion', 'SHIELD', 'knowledge-memory', 'Customers can export everything a system holds about them, and request deletion with a verifiable record.', 'CONFIGURABLE', true, '{"slug":"data-export-deletion","name":"Data Export & Deletion","family":"SHIELD","foundation":"knowledge-memory","summary":"Customers can export everything a system holds about them, and request deletion with a verifiable record.","description":"Export produces a complete, machine-readable package of a customer''s configurations, requests, memory and audit history. Deletion requests are recorded, executed across stores and confirmed with a deletion record, subject to any legal retention you are required to keep.","outcomes":["Complete machine-readable export on request","Deletion executed across stores and confirmed","Legal retention exceptions made explicit"],"integrations":["Customer dashboard"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["privacy","portability"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('memory-provenance', 'Memory Provenance', 'SHIELD', 'knowledge-memory', 'Every remembered fact keeps its source, author and time; corrections are versioned, never silent overwrites.', 'CONFIGURABLE', true, '{"slug":"memory-provenance","name":"Memory Provenance","family":"SHIELD","foundation":"knowledge-memory","summary":"Every remembered fact keeps its source, author and time; corrections are versioned, never silent overwrites.","description":"Memory Provenance attaches a source, author and timestamp to everything a system remembers. When a fact is corrected, the old version is kept with the correction and who made it, so answers can be traced and mistakes understood. Secret-like content is rejected before storage.","outcomes":["Source, author and time on every memory","Corrections versioned with who made them","Secret-like content rejected before storage"],"integrations":["All persistent systems"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["memory","provenance"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('backup-restore-drill', 'Backup & Restore Drill', 'SHIELD', 'operations', 'Scheduled backups with regular restore drills, because a backup is only proven by restoring it.', 'CONFIGURABLE', true, '{"slug":"backup-restore-drill","name":"Backup & Restore Drill","family":"SHIELD","foundation":"operations","summary":"Scheduled backups with regular restore drills, because a backup is only proven by restoring it.","description":"Backups are taken on a schedule and restore drills are run into an isolated environment to prove they work. Each drill records what was restored, how long it took and whether the result matched. A failed drill is treated as an incident.","outcomes":["Scheduled backups per system","Restore drills into isolated environments","Failed drills raised as incidents"],"integrations":["Object storage","Database snapshots"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"DELETE","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["backup","recovery"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('guardian-controls', 'Guardian Controls', 'SHIELD', 'family-play', 'Parents and teachers set what children''s profiles can see and do, with activity summaries they can review.', 'CONFIGURABLE', true, '{"slug":"guardian-controls","name":"Guardian Controls","family":"SHIELD","foundation":"family-play","summary":"Parents and teachers set what children''s profiles can see and do, with activity summaries they can review.","description":"Guardian Controls lets parents and teachers set content limits, session lengths and allowed activities for each child profile, and review activity summaries. Purchases, outside messaging and public sharing are denied for child profiles regardless of other settings.","outcomes":["Per-child content limits and session lengths","Activity summaries for guardians","Purchases and outside messaging always denied for children"],"integrations":["Family and classroom systems"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SPEND","rule":"deny"},{"action":"SEND_EXTERNAL","rule":"deny"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["children","safety"]}'::jsonb) on conflict (slug) do nothing;
insert into public.claws (slug, name, family, foundation_id, summary, maturity, published, definition) values ('spend-guard', 'Spend Guard', 'SHIELD', 'commerce-inventory', 'Every spending action needs an approval, stays within per-day and per-vendor ceilings and is logged.', 'CONFIGURABLE', true, '{"slug":"spend-guard","name":"Spend Guard","family":"SHIELD","foundation":"commerce-inventory","summary":"Every spending action needs an approval, stays within per-day and per-vendor ceilings and is logged.","description":"Spend Guard sits in front of every action that costs money — purchases, refunds, paid model calls, ad spend. Each needs an approval bound to the exact amount and payee, must fit within daily and per-vendor ceilings and is logged. Duplicate requests are detected and suppressed.","outcomes":["Approval bound to exact amount and payee","Daily and per-vendor spending ceilings","Duplicate spending requests suppressed"],"integrations":["Payment providers","Commerce platforms"],"actions":[{"action":"READ","rule":"allow"},{"action":"WRITE_INTERNAL","rule":"allow"},{"action":"SPEND","rule":"approval"},{"action":"ADMIN","rule":"deny"}],"profile":"SAFE","runtime":"control-plane","modelPolicies":["local-first","balanced"],"compute":["cpu"],"deployments":["managed-cell","private-cloud","on-prem"],"maturity":"CONFIGURABLE","tags":["spend","limits"]}'::jsonb) on conflict (slug) do nothing;
